use std::error::Error;
use std::fmt;
use std::num::ParseIntError;

// 1) 用枚举穷举所有业务失败场景
#[derive(Debug)]
enum AppError {
    Parse(ParseIntError),   // 包装型：持有底层错误
    DivByZero,              // 语义型：无底层错误
    NotFound(String),       // 语义型：携带上下文
}

// 2) 实现 Display：给「人」看的错误描述
impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AppError::Parse(e) => write!(f, "数字解析失败: {}", e),
            AppError::DivByZero => write!(f, "除数不能为 0"),
            AppError::NotFound(key) => write!(f, "配置项不存在: {}", key),
        }
    }
}

// 3) 实现 Error：用 source() 保留错误链
impl Error for AppError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            AppError::Parse(e) => Some(e), // 把根因挂上去
            _ => None,
        }
    }
}

// 4) From 转换：让 ? 能把 ParseIntError 自动变成 AppError
impl From<ParseIntError> for AppError {
    fn from(e: ParseIntError) -> Self {
        AppError::Parse(e)
    }
}

// 解析两个数并相除，全程只用 ? 传播错误
fn parse_div(a: &str, b: &str) -> Result<i64, AppError> {
    let a: i64 = a.trim().parse()?; // 失败 -> From -> 早返回
    let b: i64 = b.trim().parse()?;
    if b == 0 {
        return Err(AppError::DivByZero); // 业务错误手动构造
    }
    Ok(a / b)
}

// ok_or_else 把 Option 转成 Result（惰性构造错误，避免无谓分配）
fn find_config<'a>(map: &'a [(&str, &str)], key: &str) -> Result<&'a str, AppError> {
    map.iter()
        .find(|(k, _)| *k == key)
        .map(|(_, v)| *v)
        .ok_or_else(|| AppError::NotFound(key.to_string()))
}

fn run() -> Result<(), AppError> {
    let v = parse_div("100", "4")?;
    println!("run(): 100 / 4 = {}", v);
    Ok(())
}

fn main() {
    let cases = [("42", "6"), ("42", "0"), ("abc", "3")];
    for (a, b) in cases {
        match parse_div(a, b) {
            Ok(v) => println!("{} / {} = {}", a, b, v),
            Err(e) => println!("{} / {} -> [{}] 根因: {:?}", a, b, e, e.source()),
        }
    }

    let conf = [("host", "127.0.0.1"), ("port", "8080")];
    match find_config(&conf, "timeout") {
        Ok(v) => println!("timeout = {}", v),
        Err(e) => println!("加载失败: {}", e),
    }

    if let Err(e) = run() {
        println!("run 失败: {}", e);
    }
}

